import { brand } from './brand.js';
import { esc, icon, initials } from '../lib/html.js';
import { notifications, today, dateLabel } from '../lib/finance.js';
export const PAGES = { dashboard:'Overview', projects:'Projects', expenses:'Expenses', receipts:'Received payments', remaining:'Remaining payments', subscriptions:'Subscriptions', partners:'Partner payments', notifications:'Notifications' };
export function workspaceShell(page,content,data,preview,email) {
 const unread=notifications(data).filter(n=>!data.reads.includes(n.id)).length;
 return '<div class="workspace-app"><aside class="work-sidebar">'+brand+'<div class="workspace-switch"><span class="workspace-symbol">RT</span><div>Rayan workspace<small>Four partners. One vision.</small></div><span class="connection-dot"></span></div><div class="nav-caption">MANAGE YOUR BUSINESS</div><nav aria-label="Main navigation">'+Object.entries(PAGES).map(([key,title])=>'<a href="#'+key+'" '+(key===page?'aria-current="page"':'')+'>'+icon(key)+'<span>'+title+'</span>'+(key==='notifications'&&unread?'<b class="nav-count">'+unread+'</b>':'')+'</a>').join('')+'</nav><div class="sidebar-foot"><div class="sidebar-note"><span class="small-dot"></span> '+(preview?'Design preview':'Shared workspace')+'</div><button data-action="sign-out">'+icon('logout')+(preview?'Exit preview':'Sign out')+'</button><small>RAYAN TECH SOLUTION © '+new Date().getFullYear()+'</small></div></aside><div class="work-main"><header class="work-header"><div class="breadcrumbs">Workspace <span>/</span> <strong>'+PAGES[page]+'</strong></div><div class="header-tools"><button class="icon-button mobile-logout" data-action="sign-out" aria-label="Sign out">'+icon('logout')+'</button><span class="header-date">'+dateLabel(today())+'</span><button class="icon-button" data-action="refresh" aria-label="Refresh workspace">'+icon('refresh')+'</button><a class="bell-button" href="#notifications" aria-label="'+unread+' unread notifications">'+icon('notifications')+(unread?'<i></i>':'')+'</a><span class="user-avatar" title="'+esc(email||'Preview user')+'">'+esc(initials(email?.split('@')[0]||'Rayan Team'))+'</span></div></header>'+(preview?'<div class="demo-banner"><span>PREVIEW MODE</span> Try the forms freely. Preview records reset when you leave; they are not saved to Supabase.</div>':'')+'<main id="workspace-content" class="work-content">'+content+'</main><footer class="work-footer"><span>RAYAN TECH SOLUTION</span><span>Built for the way we work. <i></i> AFN</span></footer></div></div><dialog id="record-dialog" class="record-dialog"></dialog><div id="toast" class="toast" role="status"></div>';
}
